noteContentFormat:
{% set url = schema:@VideoObject:embedUrl|replace:"embed/":"watch?v=" %}


{% set texts = selector:.yt-core-attributed-string,.segment .segment-text %}
{% set texts = selector:.segment .segment-text %}


{% set timestamps = selector:.ytwTranscriptSegmentViewModelTimestamp,.segment .segment-timestamp %}
{% set timestamps = selector:.segment .segment-timestamp %}

![{{title}}]({{schema:@VideoObject:embedUrl|replace:"embed/":"watch?v="}})

## Transcript
{% for ts in timestamps %}
  {% set parts = ts|split:":" %}
  {% set length = parts|length %}
  {% if length >= 3 %}
    [{{ts}}]({{url}}&t={{parts|slice:0,1}}h{{parts|slice:1,2}}m{{parts|slice:2,3}}s) {{texts[loop.index0]}}
  {% else %}
    [{{ts}}]({{url}}&t={{parts|slice:0,1}}m{{parts|slice:1,2}}s) {{texts[loop.index0]}}
  {% endif %}
{% endfor %}
